import{_ as t,o as r,c as a,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Demonstration Scenario","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/demonstration-scenario.md","filePath":"get-started/demonstration-scenario.md"}'),o={name:"get-started/demonstration-scenario.md"};function s(i,e,c,l,d,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="demonstration-scenario" tabindex="-1">Demonstration Scenario <a class="header-anchor" href="#demonstration-scenario" aria-label="Permalink to &quot;Demonstration Scenario&quot;">​</a></h1><p><strong>One hero flow, five beats, under two minutes.</strong></p><ol><li><strong>Send.</strong> A plain payment screen. Enter €10, a test card, confirm. <strong>No wallet, no address, no gas.</strong> The PSP sandbox processes it and fires a real webhook.</li><li><strong>Settle.</strong> The backend executes a real stablecoin transfer on Hedera testnet. <strong>Open HashScan live</strong>, real transaction, real consensus timestamp.</li><li><strong>Anchor.</strong> The compliance record is hashed and submitted to HCS. Show the topic, the sequence number, the timestamp.</li><li><strong>Receive.</strong> The payout sandbox returns a success receipt; the UI shows the local-currency credit. <strong>The recipient never saw a blockchain.</strong></li><li><strong>The kill shot, verify, then tamper.</strong> Query the Mirror Node from a separate tab: independent proof that the check passed at that moment, with no access to our system. Then alter the off-chain compliance record and re-verify: <strong>MATCH becomes MISMATCH.</strong> No incumbent in <a href="./../business/market-analysis.html">this section</a> can do this.</li></ol><p><strong>Backup:</strong> pre-anchored records and a screen recording, in case a sandbox or the Mirror Node lags.</p><hr><h2 id="illustrative-corridor-portugal-→-armenia" tabindex="-1">Illustrative corridor: Portugal → Armenia <a class="header-anchor" href="#illustrative-corridor-portugal-→-armenia" aria-label="Permalink to &quot;Illustrative corridor: Portugal → Armenia&quot;">​</a></h2><p>A useful concrete example throughout this project: a sender in Portugal (SEPA, EUR) paying a recipient in Armenia (AMD). This corridor has no Nexus link, no G7 wholesale relevance, and thin correspondent-banking coverage from incumbent fintechs, exactly the access gap this architecture targets, distinct from a well-served EU-to-EU transfer where incumbents already compete effectively.</p>',7)])])}const u=t(o,[["render",s]]);export{p as __pageData,u as default};
